    /**
     * A steward's review of a REVIEW claim: it becomes OPEN, still unnumbered, keeping who
     * opened it; CLAIM_REVIEWED is written, then CLAIM_OPENED. Refused (403) for
     * anyone but a steward, (409) for a claim that is not REVIEW and (423) when due inside a closed
     * period.
     */
    @Transactional
    public Claim review(String sheetId, String user, long id) {
        roles.refuseViewer(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() != ClaimStatus.REVIEW) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be reviewed.");
        }
        if (!isSteward(sheetId, user)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can review a claim.");
        }
        periods.refuseIfClosed(sheetId, claim.getDueBy());
        Person person = person(sheetId, claim.getPersonId());
        claim.setStatus(ClaimStatus.OPEN);
        logStatus(sheetId, user, person, claim);
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_REVIEWED", sheetId, user, person, saved));
        audit.recordOnCommit(record("CLAIM_OPENED", sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Delete a DRAFT claim: it becomes DELETED, counts nowhere and makes no other move but a restore;
     * its status log gains a DELETED line and CLAIM_DELETED is written. Any editor's lock on it is
     * released. Refused (403) for a viewer, (409) for a claim that is not DRAFT or that another
     * user's open editor locks, and (423) when due inside a closed period.
        return saved;
    }

    /**
     * A steward's waiver of an OPEN or PENDING claim's late charge: from then on it bears none,
     * whatever its overdue state; CLAIM_WAIVED is written. Refused (403) for anyone but a steward and
     * (409) for a claim in any other status or already waived.
     */
    @Transactional
    public Claim waive(String sheetId, String user, long id) {
        roles.refuseViewer(sheetId, user);
        if (!isSteward(sheetId, user)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can waive a late charge.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim's late charge cannot be waived.");
        }
        if (claim.isWaived()) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "This claim's late charge is already waived.");
        }
        Person person = person(sheetId, claim.getPersonId());
        claim.waive();
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record("CLAIM_WAIVED", sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Hold an OPEN or PENDING claim, or release it when held: a held claim still counts in every total.
     * CLAIM_HELD or CLAIM_RELEASED is
     * written. Refused (409) for a claim in any other status.
     */
    @Transactional
    public Claim toggleHold(String sheetId, String user, long id) {
        roles.refuseViewer(sheetId, user);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet."));
        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be held or released.");
        }
        Person person = person(sheetId, claim.getPersonId());
        boolean hold = !claim.isHeld();
        claim.setHeld(hold, sheets.today(sheetId));
        Claim saved = claims.saveAndFlush(claim);
        audit.recordOnCommit(record(hold ? "CLAIM_HELD" : "CLAIM_RELEASED", sheetId, user, person, saved)
                + (saved.getNumber() != null ? " number=" + saved.getNumber() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Re-settle a SETTLED claim: fix its due again at the figure it would have on the sheet's today
     * as an open claim bound by no statement, with its late charge. Refused (403) for anyone but a
     * Whether the user is a clerk settling a claim whose figure is above the clerk limit in force: its
     * person's grade's (on the sheet's today) when one is set, else the sheet's.
     */
    private boolean aboveClerkLimit(String sheetId, String user, Person person, BigDecimal figure) {
        BigDecimal limit = figure == null ? null
                : sheets.clerkLimit(sheetId, person.gradeOn(sheets.today(sheetId)));
        return figure != null && limit != null && figure.compareTo(limit) > 0 && !isSteward(sheetId, user);
    }

    private boolean isSteward(String sheetId, String user) {
        return Role.STEWARD.equals(roles.roleOf(sheetId, user));
    }

    /**
     * The number a claim corrects: none unless its amount is negative, when it must name the number
     * of a SETTLED claim of the same person, else it is refused (400). It may not exceed what remains
     * of that claim: its amount less the corrections already made against it (VOID and DELETED ones,
     * and the claim being edited, left out), else it is refused (422).
     */
    private String corrected(String sheetId, long personId, Long editedId, BigDecimal amount, String corrects) {
        if (amount.signum() >= 0) {
            return null;
        }
        List<Claim> personClaims = corrects == null ? List.of()
                : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
        Claim target = personClaims.stream()
                .filter(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED)
                .findFirst().orElse(null);
        if (target == null) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
                    "A negative amount must correct a SETTLED claim of the same person, by its number.");
        }
        BigDecimal remaining = personClaims.stream()
                .filter(c -> corrects.equals(c.getCorrects()) && c.isCorrection()
                        && c.getStatus() != ClaimStatus.VOID && c.getStatus() != ClaimStatus.DELETED
                        && !c.getId().equals(editedId))
                .map(Claim::getAmount).reduce(target.getAmount(), BigDecimal::add);
        if (amount.negate().compareTo(remaining) > 0) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "A correction may not exceed what remains of the claim it corrects (" + remaining + ").");
        }
        return corrects;
    }

    /**
     * Refuse (422) a claim dated after its person's retirement date, or after the from-date and
     * before the to-date of one of their past retirements.
     */
    private static void refuseIfRetired(Person person, LocalDate date) {
        if (person.refusesClaimOn(date)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,
                    "That claim's date is after its person's retirement date.");
        }
    }

    private Person person(String sheetId, long personId) {
        return people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet."));
    }

    /** Refuse a reference (none when null) another claim on the sheet already has, without regard to case. */
    void refuseIfRefUsed(String sheetId, String ref, Long exceptId) {
        if (ref != null && (exceptId == null ? claims.existsBySheetIdAndRefIgnoreCase(sheetId, ref)
                : claims.existsBySheetIdAndRefIgnoreCaseAndIdNot(sheetId, ref, exceptId))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The reference " + ref + " is already used on this sheet.");
        }
    }

    /** Every tag ever used on the sheet, sorted. */
    @Transactional(readOnly = true)
    public List<String> usedTags(String sheetId) {
        return usedTags.findBySheetIdOrderByTagAsc(sheetId).stream().map(UsedTag::getTag).toList();
    }

    /** Keep each of the claim's tags as used on the sheet. */
    private void useTags(String sheetId, Claim claim) {
        for (String tag : claim.getTags()) {
            if (!usedTags.existsBySheetIdAndTag(sheetId, tag)) {
                usedTags.saveAndFlush(new UsedTag(sheetId, tag));
            }
        }
    }

    private static String record(String event, String sheetId, String user, Person person, Claim claim) {
        return event + " sheet=" + sheetId + " by=" + user + " person=" + person.getName() + " amount="
                + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString() + " date=" + claim.getDate();
    }

    private LocalDate dateOrToday(String sheetId, LocalDate date) {
        return date != null ? date : sheets.entryDate(sheetId);
    }
